def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    lengths = list(map(int, input[1:N+1]))

    lengths_sorted = sorted(lengths)
    possible = True

    for i in range(len(lengths_sorted)):
        if lengths_sorted[i] <= lengths_sorted[i-1] if i > 0 else False:
            continue
        if i > 0 and lengths_sorted[i] == lengths_sorted[i-1]:
            possible = False
            break

    if not possible:
        print("NO")
        return

    words = []
    for l in lengths:
        if not words:
            words.append('0' * l)
        else:
            last_word = words[-1]
            if len(last_word) < l:
                words.append(last_word + '0' * (l - len(last_word)))
            else:
                words.append('1' * l)

    prefix_check = True
    for i in range(len(words)):
        for j in range(len(words)):
            if i != j and words[i] == words[j][:len(words[i])]:
                prefix_check = False
                break
        if not prefix_check:
            break

    if not prefix_check:
        print("NO")
        return

    print("YES")
    for word in words:
        print(word)

